from sqlalchemy import *
from sqlalchemy.types import Uuid
metadata=MetaData()
definitions=Table("strategy_definitions",metadata,Column("definition_id",Uuid,primary_key=True),Column("name",String,unique=True,nullable=False),Column("kind",String,nullable=False),Column("purpose",String,nullable=False),Column("asset_scope",String,nullable=False),Column("decision_frequency",String,nullable=False),Column("rebalance_frequency",String,nullable=False),Column("benchmark",String,nullable=False),Column("owner",String,nullable=False),Column("invalidation_conditions",JSON,nullable=False))
versions=Table("strategy_versions",metadata,Column("version_id",Uuid,primary_key=True),Column("definition_id",Uuid,ForeignKey("strategy_definitions.definition_id"),nullable=False),Column("version",String,nullable=False),Column("code_version",String,nullable=False),Column("required_features",JSON,nullable=False),Column("default_parameters",JSON,nullable=False),Column("active",Boolean,nullable=False),UniqueConstraint("definition_id","version"))
runs=Table("strategy_runs",metadata,Column("run_id",Uuid,primary_key=True),Column("kind",String,nullable=False),Column("version_id",Uuid,ForeignKey("strategy_versions.version_id"),nullable=False),Column("decision_at",DateTime(timezone=True),nullable=False),Column("universe_snapshot_id",Uuid,nullable=False),Column("feature_set_id",Uuid,nullable=False),Column("data_snapshot_id",Uuid,nullable=False),Column("parameter_hash",String,nullable=False),Column("input_hash",String,unique=True,nullable=False),Column("result_hash",String,nullable=False),Column("status",String,nullable=False),Column("cash_gate",Boolean,nullable=False),Column("previous_run_id",Uuid),Column("supersedes_run_id",Uuid))
scores=Table("strategy_scores",metadata,Column("score_id",Uuid,primary_key=True),Column("run_id",Uuid,ForeignKey("strategy_runs.run_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("raw_score",Numeric,nullable=False),Column("rank",Integer,nullable=False),UniqueConstraint("run_id","instrument_id"))
candidates=Table("strategy_candidates",metadata,Column("candidate_id",Uuid,primary_key=True),Column("run_id",Uuid,ForeignKey("strategy_runs.run_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("action",String,nullable=False),Column("raw_score",Numeric),Column("rank",Integer),Column("proposed_weight",Numeric,nullable=False),Column("reason_codes",JSON,nullable=False),UniqueConstraint("run_id","instrument_id"),CheckConstraint("proposed_weight>=0 AND proposed_weight<=1"))
contributions=Table("strategy_contributions",metadata,Column("contribution_id",Uuid,primary_key=True),Column("run_id",Uuid,ForeignKey("strategy_runs.run_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("feature_name",String,nullable=False),Column("feature_value",Numeric,nullable=False),Column("weight",Numeric,nullable=False),Column("contribution",Numeric,nullable=False),UniqueConstraint("run_id","instrument_id","feature_name"))
evidence_table=Table("research_evidence",metadata,Column("evidence_id",Uuid,primary_key=True),Column("strategy_version_id",Uuid,ForeignKey("strategy_versions.version_id"),nullable=False),Column("evidence_type",String,nullable=False),Column("sample_start",String,nullable=False),Column("sample_end",String,nullable=False),Column("artifact_ref",String,nullable=False),Column("parameters_hash",String,nullable=False))
events=Table("strategy_events",metadata,Column("event_id",Uuid,primary_key=True),Column("event_type",String,nullable=False),Column("run_id",Uuid,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False),Column("reasons",JSON,nullable=False))
